--战斗
function UIJackpotDungoenChallengeDialog:OnBtnBattle()
    local isOpne = HalloweenUtils.IsOpen()
    if not isOpne then
        GameUtils.Toast(localize("活动已结束"))
        return
    end

    local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(self._curSelectId)
    if not isUnlock then 
        GameUtils.Toast(localize("该关卡未解锁"))
        return
    end

    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectId)
    if GoodsUtils.GetThingNo(vo.costItem) < checkNumber(vo.costNum) then
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.costItem)
        GameUtils.Toast(localize("_name_不足，请前往「集章兑换」获得", {_name_ = goodsVo.name}))
        return
    end

   --local isPassAll = QuestConfMgr:GetInstance():IsPassAllNightCatQuestTowerQuest()
   --if isPassAll then
   --    GameUtils.Toast(localize("已通关全部"))
   --    return
   --end

    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self._curSelectId, activityUuid = comp:GetUuid() } }, {
        { id = Constants.UITypeIds.UIJackpotDungoenChallengeDialog },
    })
end

