function UIJackpotDungoenChallengeDialog:InitData()
    self._allQuestId = HalloweenUtils.GetAllChallengeQuest(self._activityId)
    local data = comp:GetQuestInfo()
    if checkNumber(data.newQuestId) == 0 then
        self._curSelectId = self._allQuestId[1]
    else
        self._curSelectId = checkNumber(data.newQuestId)
    end

    local lastId = KCookie.Get("LastHalloween") 
    if checkNumber(lastId) > 0 then
        self._curSelectId = checkNumber(lastId)
    end
end

function UIJackpotDungoenChallengeDialog:FillSelf()
    self:FillQuests()

    self:FillRewards()
    self:FillConsumeInfo()
end

function UIJackpotDungoenChallengeDialog:FillConsumeInfo()
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curSelectId)
    CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, vo.costItem, vo.costNum)
end

function UIJackpotDungoenChallengeDialog:FillRewards()
    local t = RewardConfMgr:GetInstance():GetTeamShowRewardData(self._curSelectId)
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsList)
    if scr then
        scr:FreshBaseUI(t, false)
        if scr then
            scr:FreshBaseUI(t)
        end
        for k, v in pairs(t) do
            local go = self.CommonGoodsList.transform:Find("GoodNode"..k)
            if go then
                CfUtils.SetActive(go.transform:Find("Container/LvBg"), checkNumber(v.num) > 0)
                CfUtils.SetActive(go.transform:Find("Container/ImgNumBg"), checkNumber(v.num) > 0)
            end
        end
    end
end

function UIJackpotDungoenChallengeDialog:FillReward()
end


function UIJackpotDungoenChallengeDialog:FillQuests()
    for k, v in pairs(self._allQuestId) do
        self:FillQuest(self["Cell"..k], v)
    end
end

function UIJackpotDungoenChallengeDialog:FillQuest(go, questId)
    local type = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not vo then
        return
    end

    local btnGo = go.transform:Find("Btn")
    CfUtils.FillText(btnGo.transform:Find("TxtDifficult"), vo.label)

    local isPass = QuestConfMgr:GetInstance():IsPassQuest(questId)
    local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(questId)

    CfUtils.SetActive(btnGo.transform:Find("LockGroup"), not isUnlock)

    CfUtils.SetActive(btnGo.transform:Find("SelectGroup"), checkNumber(self._curSelectId) == checkNumber(questId))
    CfUtils.SetUISwitchImage(btnGo.transform:Find("ImgBg"), checkNumber(self._curSelectId) == checkNumber(questId) and 2 or 1)

    SetButtonAction(btnGo, function()
        if not isUnlock then
            GameUtils.Toast(localize("该关卡未解锁"))
            return
        end

        local ind = table.indexof(self._allQuestId, checkString(self._curSelectId))
        if checkNumber(ind) > 0 then
            local lastGo = self["Cell"..ind]
            if lastGo then
                CfUtils.SetActive(lastGo.transform:Find("Btn/SelectGroup"), false)
                CfUtils.SetUISwitchImage(lastGo.transform:Find("Btn/ImgBg"), 1)
            end
        end

        self._curSelectId = questId
        CfUtils.SetActive(btnGo.transform:Find("SelectGroup"), true)
        CfUtils.SetUISwitchImage(btnGo.transform:Find("ImgBg"), 2)

        self:FillRewards()
        self:FillConsumeInfo()
    end)
end

